// SA V2 / SC Review V2 - helpers every package uses (SUBMIT, PREPARE, COMMIT, WORKER, client). Copied from smv2
// code/shared/lot_common.js (with f8's lotParseJ fix) and renamed sa / SA_. Included into a code node by the builders
// (v2build.include_js drops the "if (typeof module" line); every top-level name carries the sa / SA_ prefix so the file
// concatenates with a step's own helpers (s, q8, list, digits, parseJ) without a redeclaration.
const saS = (v) => (v === undefined || v === null ? "" : String(v)).trim();
// q8: the 8-dp rounding of COMPUTED quantities (STOCK_ADJUSTMENT code_node_O4tWJ5JH's q8); a NUMBER
const saQ8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
// a decimal as the 8-dp text the platform stores, never negative; a STRING
const saQtyStr = (v) => Math.max(0, saQ8(v)).toFixed(8);
const saDigits = (v) => /^[0-9]{1,20}$/.test(saS(v));
// a bigint id as a digit string: a digit string as is, a SAFE non-negative integer number as its digits; anything else
// (a 19-digit id that already went through a JS number, "", null, text) -> ""
const saIdStr = (v) => {
  if (typeof v === "number") return Number.isSafeInteger(v) && v >= 0 ? String(v) : "";
  const t = saS(v);
  return /^[0-9]{1,20}$/.test(t) ? t : "";
};
// JSON text with every bare 16+ digit integer TOKEN read as a STRING (snowflake ids survive); only whole integer tokens -
// never the fraction digits of a float such as 0.30000000000000004; null when it does not parse
const saParseJ = (t) => {
  if (t === undefined || t === null) return null;
  if (typeof t === "object") return t;
  try {
    return JSON.parse(String(t).replace(/"(?:[^"\\]|\\.)*"|(^\s*|[:\[,]\s*)(-?\d{16,})(?=\s*(?:[,\]}]|$))/g, (m, pre, num) => (num === undefined ? m : pre + '"' + num + '"')));
  } catch (e) {
    return null;
  }
};
const saList = (x) => (Array.isArray(x) ? x : x ? [x] : []).filter((r) => r !== undefined && r !== null);
// a JSON-text-or-array column (balance_index, reference_documents): the array, [] when empty / not a list
const saJsonList = (v) => {
  if (Array.isArray(v)) return v;
  const t = saS(v);
  if (!t) return [];
  const p = saParseJ(t);
  return Array.isArray(p) ? p : [];
};
// sql-node rows: JSON_OBJECT rows ({ j: "<json>" }) or already-plain objects -> plain objects (ids of 16+ digits as strings)
const saRows = (rows) => saList(rows).map((r) => (r && typeof r === "object" && typeof r.j === "string" ? saParseJ(r.j) : r)).filter((r) => r && typeof r === "object");
// STOCK_ADJUSTMENT code_node_GmKmvMGe: balance.category || "Unrestricted"
const saCategory = (c) => saS(c) || "Unrestricted";
// an entry's movement_type -> "ADD" (in) / "SUBTRACT" (out) / "" (invalid); readers are case-insensitive (prod holds
// In / IN / Out / OUT); the STORED casing is never rewritten (AutoCount V2 posting compares it exactly)
const saDirection = (mt) => {
  const t = saS(mt).toLowerCase();
  return t === "in" ? "ADD" : t === "out" ? "SUBTRACT" : "";
};
// UTF-8 byte length of a balance_index value (the column is TEXT, 65,535 bytes; prod's non-strict sql_mode truncates)
const saUtf8Bytes = (v) => {
  const t = Array.isArray(v) || (v && typeof v === "object") ? JSON.stringify(v) : saS(v);
  let n = 0;
  for (let i = 0; i < t.length; i++) {
    const c = t.charCodeAt(i);
    if (c < 0x80) n += 1;
    else if (c < 0x800) n += 2;
    else if (c >= 0xd800 && c <= 0xdbff) { n += 4; i++; }
    else n += 3;
  }
  return n;
};
const SA_LINE_MAX_BYTES = 60000;
const SA_MAX_ENTRIES = 5000;
const SA_CLASSIC_MAX_ENTRIES = 500;
const SA_REVIEW_LINE_MAX_ENTRIES = 50;
const saDbAddSeconds = function saDbAddSeconds(text, seconds) {
  const m = String(text || "").match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})/);
  if (!m) return "";
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]), Number(m[4]), Number(m[5]), Number(m[6])) + seconds * 1000);
  const p = (n) => (n < 10 ? "0" : "") + n;
  return d.getUTCFullYear() + "-" + p(d.getUTCMonth() + 1) + "-" + p(d.getUTCDate()) + " " + p(d.getUTCHours()) + ":" + p(d.getUTCMinutes()) + ":" + p(d.getUTCSeconds());
};
// the bounded statuses a COMPLETE_SA job may restore (CONTRACT.md §2): FORM -> Draft, REVIEW -> Cancelled; anything else =
// unknown = no unlock, REQUIRES_REVIEW SA_PREV_STATUS_UNKNOWN
const SA_PREV_STATUSES = ["Draft", "Cancelled"];
const saPrevStatusOk = (v) => SA_PREV_STATUSES.indexOf(saS(v)) >= 0;
// the payload part rows of one value: step_name <prefix><nnn>, 400,000 characters each (GR / Putaway / LOT V2's chunking)
const SA_CHUNK = 400000;
const saPartRows = function saPartRows(jobId, organizationId, prefix, value, status) {
  const text = JSON.stringify(value);
  const out = [];
  for (let at = 0, n = 1; at < text.length || n === 1; at += SA_CHUNK, n++) {
    out.push({ job_id: saS(jobId), organization_id: saS(organizationId), step_name: prefix + String(n).padStart(3, "0"), step_status: status || "PAYLOAD", attempt_count: 0,
      result_ref: text.slice(at, at + SA_CHUNK) });
  }
  return out;
};
// a part's chunk rows (step_name <prefix>nnn) joined in step-name order -> the value; null when there is no row, undefined
// when the joined text does not parse (GR's joinChunks)
const saJoinChunks = function saJoinChunks(rows, prefix) {
  const mine = saList(rows).filter((r) => saS(r.step_name).indexOf(prefix) === 0).sort((a, b) => (saS(a.step_name) < saS(b.step_name) ? -1 : 1));
  if (!mine.length) return null;
  const p = saParseJ(mine.map((r) => (r.result_ref === undefined || r.result_ref === null ? "" : String(r.result_ref))).join(""));
  return p === null ? undefined : p;
};
// SA V2 guard (CONTRACT §11): payload only - a completion of > 500 entries (sa_quantity > 0, as code_node_qrsgEz2F), or any
// balance_index > 60,000 UTF-8 bytes (prod truncates the TEXT column silently), or a moving entry in Reserved (another document holds
// that stock: an Item Assembly hold, a GD / SO reservation), is refused; odd shapes pass through.
const saGuardIn = { allData: [{{workflowparams:allData}}][0], saveAs: [{{workflowparams:saveAs}}][0], tenantId: [{{system:tenantId}}][0] };
let saGuardDoc = saGuardIn.allData;
if (typeof saGuardDoc === "string") saGuardDoc = saParseJ(saGuardDoc);
if (!saGuardDoc || typeof saGuardDoc !== "object" || Array.isArray(saGuardDoc)) saGuardDoc = {};
let saId = "0";
let tenantId = "0";
try {
  const t = saS(saGuardIn.tenantId);
  const id = saIdStr(saGuardDoc.id);
  if (saDigits(t) && saDigits(id)) {
    saId = id;
    tenantId = t;
  }
} catch (e) {
  saId = "0";
  tenantId = "0";
}
let entries = 0;
let reason = "";
let message = "";
try {
  let large = null;
  let reserved = 0;
  const lines = Array.isArray(saGuardDoc.stock_adjustment) ? saGuardDoc.stock_adjustment : [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line || typeof line !== "object") continue;
    const bytes = saUtf8Bytes(line.balance_index);
    if (!large && bytes > SA_LINE_MAX_BYTES) large = { line: i + 1, bytes: bytes };
    for (const e of saJsonList(line.balance_index)) {
      if (!e || typeof e !== "object" || !(e.sa_quantity > 0)) continue;
      entries++;
      if (!reserved && saS(e.category).trim().toLowerCase() === "reserved") reserved = i + 1;
    }
  }
  const saveAs = saGuardIn.saveAs === undefined || saGuardIn.saveAs === null ? "" : String(saGuardIn.saveAs);
  if (saveAs !== "Draft" && entries > SA_CLASSIC_MAX_ENTRIES) {
    reason = "SA_CLASSIC_TOO_BIG";
    message = "This Stock Adjustment has " + entries + " entries. Adjust at most " + SA_CLASSIC_MAX_ENTRIES + " at a time.";
  } else if (saveAs !== "Draft" && reserved) {
    reason = "SA_RESERVED";
    message = "Line " + reserved + ": Reserved stock belongs to another document. Release it there first.";
  } else if (large) {
    reason = "SA_LINE_TOO_LARGE";
    message = "Line " + large.line + " holds too many bins (" + large.bytes + " bytes); split it into several lines.";
  }
} catch (e) {
  reason = "";
  message = "";
}
return { saId: saId, tenantId: tenantId, entries: String(entries), reason: reason, message: message };

// The STORED status decides first: a Processing SA belongs to a background save (any classic save would overwrite it).
const saGuardRows = [{{node:sql_node_SAguard.data}}][0];
const saGuardOut = [{{node:code_node_SAguard.data}}][0] || {};
let busy = false;
try {
  const rows = Array.isArray(saGuardRows) ? saGuardRows : saGuardRows && typeof saGuardRows === "object" ? [saGuardRows] : [];
  busy = rows.some((r) => r && typeof r === "object" && String(r.stock_adjustment_status) === "Processing");
} catch (e) {
  busy = false;
}
const reason = busy ? "SA_BUSY" : String(saGuardOut.reason || "");
const message = busy ? "This Stock Adjustment is being processed in the background - please wait for it to finish." : String(saGuardOut.message || "");
return { refuse: reason && message ? "YES" : "NO", reason: reason, message: message };

let allData = {{workflowparams:allData}}
const updatedSA = []
const saveAs = {{workflowparams:saveAs}}

// 8dp is the maximum configurable column precision: rounding there keeps every
// client-configured scale intact while killing float residue.
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));

for (const [index, saLineItem] of allData.stock_adjustment.entries()) {
  saLineItem.unit_price = q8(saLineItem.unit_price);

  saLineItem.plant_id = allData.plant_id || null;
  saLineItem.line_index = index + 1;

  updatedSA.push(saLineItem)
}

allData.stock_adjustment = updatedSA

if ({{workflowparams:pageStatus}} === "Add") {
  allData.stock_adjustment_status = "Draft"
}

if (saveAs === "Draft") {
  if(allData.adjustment_no_type !== -9999 && (
  !allData.adjustment_no || allData.adjustment_no === null || allData.adjustment_no === ''
)) {
  allData.adjustment_no = 'draft'
  }
} else {
  if (
  allData.adjustment_no_type !== -9999 &&
  (!allData.adjustment_no ||
    allData.adjustment_no === null ||
    allData.adjustment_no === "" ||
    allData.stock_adjustment_status !== "In Progress")
) {
  allData.adjustment_no = 'issued'
  }
}

if (allData.acc_integration_type !== "No Accounting Integration") {
  allData.posted_status = "Unposted";
} else {
  allData.posted_status = "";
}

return {
  allData: allData,
  stock_adjustment_status: allData.stock_adjustment_status,
  stock_count_id: allData.stock_count_id || null,
}

return {
  required_fields: JSON.stringify([
      { name: "adjustment_date", label: "Adjustment Date" },
      { name: "adjustment_type", label: "Adjustment Type" },
      { name: "plant_id", label: "Plant" },
      {
        name: "stock_adjustment",
        label: "Stock Adjustment Details",
        isArray: true,
        arrayType: "object",
        arrayFields: [],
      },
    ]),
  data: JSON.stringify({
    adjustment_date: {{node:code_node_O4tWJ5JH.data.allData.adjustment_date}},
    adjustment_type: {{node:code_node_O4tWJ5JH.data.allData.adjustment_type}},
    plant_id: {{node:code_node_O4tWJ5JH.data.allData.plant_id}},
    stock_adjustment: {{node:code_node_O4tWJ5JH.data.allData.stock_adjustment}},
  })
}

// One batched Item fetch for the whole subform (was: one get-node per
// iteration inside the loop).
const rows = {{node:code_node_O4tWJ5JH.data.allData.stock_adjustment}} || [];
const itemIDs = [...new Set(rows.filter(i => i.item_selection).map(i => i.item_selection))];
return { itemIDs: itemIDs };

const page_status = {{workflowparams:pageStatus}};
const stock_adjustment_status = {{node:code_node_O4tWJ5JH.data.stock_adjustment_status}}
let allData;

if (page_status === "Add") {
  const rawData = {{node:add_node_Yk7ukSPp.data}}
  allData = Array.isArray(rawData) ? rawData[0] : rawData;
} else if (page_status === "Edit" && stock_adjustment_status === "Draft") {
  allData = {{node:get_node_Rs3nGg9f.data.data}}
} else {
  allData = {{node:code_node_O4tWJ5JH.data.allData}}
}

// Row straight from the loop variable — no redis index counter. The keys were
// scoped only on adjusted_by AND shared verbatim with LOT/MSR/PT-old, so
// concurrent saves corrupted each other's index.
// The allData branch above is kept: adjustment_no is DB-generated.
const item = {{node:loop_Jhtr4lro}};

const plant_id = allData.plant_id;
const organization_id = allData.organization_id;
const stock_adjustment_no = allData.adjustment_no;
const doc_date = allData.adjustment_date;

const material_id = item.material_id;
const material_uom = item.uom_id || "";
const total_quantity = item.total_quantity;
const remark = item.item_remark || null;
const remark2 = item.item_remark2 || null;
const remark3 = item.item_remark3 || null;
const inventory_category = item.item_category || "Unrestricted";
const unit_price = parseFloat(item.unit_price) || 0;

let tempDataParsed;

const tempData = item.balance_index;
if (!tempData) {
  tempDataParsed = [];
} else {
  tempDataParsed = JSON.parse(tempData);
  tempDataParsed = tempDataParsed.filter(
    (tempData) => tempData.sa_quantity > 0
  );
  if (!Array.isArray(tempDataParsed)) {
    tempDataParsed = [];
  }
}

// itemData for the inventory sub-workflows, from the single batched Item fetch
// (previously one get-node per loop iteration).
const itemsRaw = {{node:search_node_SAItems.data.data}} || [];
const itemsArr = Array.isArray(itemsRaw) ? itemsRaw : [itemsRaw];
const itemData = itemsArr.find(i => i && String(i.id) === String(material_id)) || null;

return {
  itemData: itemData,
  plant_id: plant_id,
  organization_id: organization_id,
  stock_adjustment_no: stock_adjustment_no,
  material_id: material_id,
  material_uom: material_uom,
  unit_price: unit_price,
  doc_date: doc_date,
  remark: remark,
  remark2: remark2,
  remark3: remark3,
  balancesToProcess: tempDataParsed
};

const saveAs = {{workflowparams:saveAs}}

// Balance straight from the loop variable — no redis index counter.
const balance = {{node:loop_NygsPXBU}};
const batch_id = balance.batch_id || null;
const location_id = balance.location_id;
const plant_id = balance.plant_id || {{node:code_node_qrsgEz2F.data.plant_id}};
const quantity = balance.sa_quantity;
let inventory_category = balance.category || "Unrestricted";
const manufacturing_date = balance.manufacturing_date || null;
const expired_date = balance.expired_date || null;
const movement_type = balance.movement_type.toLowerCase();

return {
  batch_id: batch_id,
  location_id: location_id,
  plant_id: plant_id,
  quantity: quantity,
  inventory_category: inventory_category,
  manufacturing_date: manufacturing_date,
  expired_date: expired_date,
  movement_type: movement_type
};

const scData = {{node:get_node_jN1E0Ycx.data.data}};
const table_stock_count = scData.table_stock_count;

const totalData = table_stock_count.length;
const AdjustedData = table_stock_count.filter((item) => item.line_status === "Adjusted")
const totalAdjusted = AdjustedData.length;

let adjustmentStatus
if (totalData === totalAdjusted) {
  adjustmentStatus = "Fully Adjusted"
} else {
  adjustmentStatus = "Partially Adjusted"
}

return {
  adjustmentStatus
}

const tableSA = {{node:code_node_O4tWJ5JH.data.allData.stock_adjustment}}

const uniqueItemIds = [
  ...new Set(
    tableSA
      .filter((item) => item.material_id)
      .map((item) => item.material_id),
  ),
];

const date = new Date().toISOString();
const updates = [];

for (const itemId of uniqueItemIds) {
  updates.push({
    id: itemId,
    last_transaction_date: date,
  });
}

return {
  updates: updates,
};
